// HasVersion applies the HasEdge predicate on the "version" edge.
func HasVersion() predicate.CreativeAsset {
	return predicate.CreativeAsset(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, VersionTable, VersionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasVersionWith applies the HasEdge predicate on the "version" edge with a given conditions (other predicates).
func HasVersionWith(preds ...predicate.CreativeVersion) predicate.CreativeAsset {
	return predicate.CreativeAsset(func(s *sql.Selector) {
		step := newVersionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CreativeAsset) predicate.CreativeAsset {
	return predicate.CreativeAsset(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CreativeAsset) predicate.CreativeAsset {
	return predicate.CreativeAsset(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CreativeAsset) predicate.CreativeAsset {
	return predicate.CreativeAsset(sql.NotPredicates(p))
}
